window.addEventListener('DOMContentLoaded',()=>{
const fold=s=>s.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
function enhance(){document.querySelectorAll('.account-icon-options').forEach(gallery=>{if(gallery.closest('.identity-advanced')?.dataset.libraryManager||gallery.dataset.searchReady||gallery.querySelectorAll(':scope > button').length<10)return;gallery.dataset.searchReady='yes';const input=document.createElement('input');input.type='search';input.placeholder='Buscar ícone: pão, forno, colher…';input.setAttribute('aria-label','Buscar na biblioteca de ícones');input.style.cssText='width:100%;flex-basis:100%';input.oninput=()=>gallery.querySelectorAll(':scope > button').forEach(b=>{b.hidden=b.dataset.libraryHidden==='true'||!fold(b.title).includes(fold(input.value))});gallery.prepend(input)})}
new MutationObserver(enhance).observe(document.body,{childList:true,subtree:true});enhance();
});

window.CicluzIdentity={compact:value=>Array.from(new Intl.Segmenter('pt-BR',{granularity:'grapheme'}).segment(String(value||'').trim()),x=>x.segment).slice(0,3).join(''),controls(parent,data,onchange,opts={}){const wrap=document.createElement('div');wrap.className='identity-mode-fields';const label=document.createElement('label');label.textContent='Identificador';const mode=document.createElement('select');mode.add(new Option('Ícone','icon'));mode.add(new Option('3 caracteres','text'));mode.value=data.identityMode||'icon';label.append(mode);const codeLabel=document.createElement('label');codeLabel.textContent='Até 3 caracteres';const code=document.createElement('input');code.value=this.compact(data.sigla||'').toLocaleUpperCase('pt-BR');code.maxLength=3;code.autocomplete='off';code.setAttribute('aria-label','Até 3 caracteres');codeLabel.append(code);wrap.append(label,codeLabel);parent.prepend(wrap);const up=v=>this.compact(v).toLocaleUpperCase('pt-BR'),sugerido=()=>up(String(opts.suggest?.()??'').replace(/s+/g,''));let manual=!!code.value&&code.value!==sugerido();const refresh=()=>{code.value=up(code.value);codeLabel.hidden=mode.value!=='text';code.required=mode.value==='text';onchange?.()};mode.onchange=refresh;code.oninput=()=>{manual=code.value.trim()!=='';if(!manual)code.value=sugerido();refresh()};return {mode,code,refresh,suggest:()=>{if(!manual){code.value=sugerido();refresh()}},value:()=>({identityMode:mode.value,sigla:up(code.value)})}}};
